pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    event NewProposal(address indexed member, uint indexed proposalID, string proposalType);

    function setUp() public { c = new C(); }

    // fuzz recipient and amount to let fuzzer find divergence
    function testFuzz_property(address recipient, uint256 amount) public {
        // keep recipient non-zero to be meaningful but still wide
        // allow zero too; do not overconstrain
        // Call newGrantProposal and capture emitted event via try/catch + logs

        // record proposalCount before
        uint256 before = c.proposalCount();

        // perform call and capture logs
        vm.prank(address(this));
        // emit will be in tx logs; call and then read last log
        c.newGrantProposal(recipient, amount);

        // read proposalCount after
        uint256 after = c.proposalCount();

        // We assert that the event's proposalID equals the public proposalCount after the call.
        // Retrieve the last log and decode the NewProposal event's proposalID
        // forge-std Test provides access to vm.getRecordedLogs via events capture, but
        // we can instead re-derive expected behavior: the reference contract writes mapPID_type
        // and mapPID_grant at index = previous proposalCount + 1 and then increments proposalCount,
        // so the emitted proposalID equals after. The mutant emits proposalCount (incremented later)
        // as the event argument that can differ. We therefore assert equality between the
        // public proposalCount and the emitted argument by re-emitting via a view: however Solidity
        // cannot read past event logs; instead we use the guarantee that the NewProposal event was
        // emitted with the proposalID equal to the value used as an index when storing the proposal data.
        // We can check consistency by calling public getters that reflect storage at that index.

        // The reference writes grant data to index (after) and the mutant writes to index (before).
        // Therefore, check that the grant stored at index `after` has recipient equal to the provided recipient.
        // For the reference this holds for all inputs; for the mutant there exist inputs where mapPID_grant[after]
        // will be empty (zero address) while mapPID_grant[before] holds the data — the fuzzer can find such inputs.

        // Accessing public mapping mapPID_grant via autogenerated getter: mapPID_grant(uint) returns (address recipient, uint amount)
        (address storedRecipient, uint storedAmount) = c.mapPID_grant(after);

        // Single assertion: stored data at index == after matches the call arguments
        assertTrue(storedRecipient == recipient && storedAmount == amount);
    }
}

