pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: recipient address and an amount. We use them to call newGrantProposal.
    // General rule: The reference implementation increments proposalCount after computing the new id
    // so that the stored grant is at index oldCount+1 and the public proposalCount reflects that.
    // We assert that the public proposalCount is > 0 and that the getter for proposalCount equals
    // the index one greater than the stored grant index used internally (observed by reading proposalCount
    // BEFORE and AFTER the call). The mutant that moves increment will cause a mismatch for some inputs.
    function testFuzz_property(address recipient, uint256 amount) public {
        // keep recipient within non-zero or zero allowed; no tight constraints
        // record pre-call proposalCount
        uint256 before = c.proposalCount();

        // perform the call
        bool ok;
        try c.newGrantProposal(recipient, amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // read post-call proposalCount
        uint256 after = c.proposalCount();

        // The invariant we check: if the call succeeded, then after == before + 1
        // This leverages the fact that reference C increments proposalCount as part of creating a new proposal
        // and therefore the public getter reflects the next proposal id; the mutant that delays the increment
        // will produce a different relationship for some inputs and thus fail this assertion.
        if (ok) {
            assertTrue(after == before + 1);
        } else {
            // If the call reverted, still assert that state didn't change (defensive): after == before
            assertTrue(after == before);
        }
    }
}

