pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameter: an initial proposalCount seed value to exercise different starting states
    function testFuzz_property(uint256 seed) public {
        // keep seed in a wide but reasonable domain so we avoid overflow when incrementing
        uint256 bounded = bound(seed, 0, type(uint256).max - 10);

        // We cannot directly set proposalCount (it's public but not writable), so we simulate by
        // creating (bounded) number of dummy proposals using newAddressProposal to advance the counter.
        // Use an address and type string that are valid.
        address dummyAddr = address(0x1234);
        // advance to bounded value
        for (uint256 i = 0; i < bounded; ++i) {
            // calling newAddressProposal increments proposalCount by 1 in both ref and mutant
            c.newAddressProposal(dummyAddr, "DUMMY");
        }

        // read the proposalCount before the tested call
        uint256 before = c.proposalCount();

        // call newGrantProposal once
        c.newGrantProposal(address(0xABCD), 1);

        // read after
        uint256 after = c.proposalCount();

        // The general rule: after == before + 1 for the reference implementation for ALL inputs.
        // The mutant increments by 2 so for some starting before values the equality will fail.
        assertTrue(after == before + 1);
    }
}

